{"function":"() => {
  // Let's get all order rows/cards
  // In orders-v3, each order row has a specific structure
  // Let's find all order IDs
  const orderLinks = Array.from(document.querySelectorAll('a[href*="/orders-v3/order/"]'));

  const parsedOrders = orderLinks.map(link => {
    const orderId = link.innerText.trim();
    // Find the order row container
    let container = link;
    while (container && !container.classList.contains('a-box-inner') && container !== document.body) {
      container = container.parentElement;
    }
    const fullText = container ? container.innerText : '';

    // Date regex: e.g. 2026/10/29\n20:29 PDT or 2026/10/28
    const dateMatch = fullText.match(/(\d{4}\/\d{2}\/\d{2})\s*(\d{2}:\d{2}\s*[A-Z]{3})?/);
    const orderDate = dateMatch ? dateMatch[1] : 'Unknown';
    const orderTime = dateMatch ? (dateMatch[2] || '') : '';

    // Marketplace / Channel
    const channelMatch = fullText.match(/销售渠道:\s*([^\n]+)/);
    const channel = channelMatch ? channelMatch[1].trim() : 'Unknown';

    // Business buyer
    const isBusiness = fullText.includes('企业买家');

    // Product Title
    // ASIN
    const asinMatch = fullText.match(/ASIN:\s*([A-Z0-9]{10})/);
    const asin = asinMatch ? asinMatch[1] : 'Unknown';

    // SKU
    const skuMatch = fullText.match(/SKU:\s*([^\n]+)/);
    const sku = skuMatch ? skuMatch[1].trim() : 'Unknown';

    // Quantity
    const qtyMatch = fullText.match(/数量:\s*(\d+)/);
    const qty = qtyMatch ? parseInt(qtyMatch[1], 10) : 1;

    // Subtotal
    const subtotalMatch = fullText.match(/商品小计:\s*([^\n]+)/);
    const subtotal = subtotalMatch ? subtotalMatch[1].trim() : 'Unknown';

    // Product Title: usually before ASIN
    let title = 'Unknown';
    if (asinMatch) {
      const beforeAsin = fullText.slice(0, asinMatch.index);
      const lines = beforeAsin.split('\n').map(l => l.trim()).filter(Boolean);
      // Title is usually the last line or two before ASIN:
      // Filter out metadata lines like "卖家订单编号", "销售渠道", "配送渠道", etc.
      const candidateLines = lines.filter(l => 
        !l.includes('配送渠道') && 
        !l.includes('销售渠道') && 
        !l.includes('卖家订单编号') && 
        !l.includes('企业买家') && 
        !l.includes('买家姓名') && 
        !l.includes('PDT') && 
        !l.includes('PST') && 
        !l.includes('订单详情') && 
        !l.includes('订单日期') && 
        !l.includes('前') && 
        !l.includes(orderId)
      );
      if (candidateLines.length > 0) {
        title = candidateLines[candidateLines.length - 1];
      }
    }

    return {
      orderId,
      orderDate,
      orderTime,
      channel,
      isBusiness,
      asin,
      sku,
      title,
      qty,
      subtotal
    };
  });

  return parsedOrders;
}","pageId":3,"toolSummary":"Parse all 38 pending orders with details"}

