{"function":"() => {
  const table = document.getElementById('orders-table');
  if (!table) return { error: 'no table' };

  const trs = Array.from(table.querySelectorAll('tbody tr')).filter(tr => tr.querySelector('a[href*="/orders-v3/order/"]'));

  const parsed = trs.map(tr => {
    const text = tr.innerText;
    const link = tr.querySelector('a[href*="/orders-v3/order/"]');
    const orderId = link ? link.innerText.trim() : 'Unknown';

    // Date regex
    const dateMatch = text.match(/(\d{4}\/\d{2}\/\d{2})\s*(\d{2}:\d{2}\s*[A-Z]{3})?/);
    const orderDate = dateMatch ? dateMatch[1] : 'Unknown';
    const orderTime = dateMatch ? (dateMatch[2] || '') : '';

    // Channel
    const channelMatch = text.match(/销售渠道:\s*([^\n\t]+)/);
    const channel = channelMatch ? channelMatch[1].trim() : 'Unknown';

    // Business buyer
    const isBusiness = text.includes('企业买家');

    // ASIN
    const asinMatch = text.match(/ASIN:\s*([A-Z0-9]{10})/);
    const asin = asinMatch ? asinMatch[1] : 'Unknown';

    // SKU
    const skuMatch = text.match(/SKU:\s*([^\n\t]+)/);
    const sku = skuMatch ? skuMatch[1].trim() : 'Unknown';

    // Quantity
    const qtyMatch = text.match(/数量:\s*(\d+)/);
    const qty = qtyMatch ? parseInt(qtyMatch[1], 10) : 1;

    // Subtotal
    const subtotalMatch = text.match(/商品小计:\s*([^\n\t]+)/);
    const subtotal = subtotalMatch ? subtotalMatch[1].trim() : 'Unknown';

    // Title
    // In the row, td 3 or 4 contains product info. Let's find the element with ASIN
    let title = 'Unknown';
    const tds = tr.querySelectorAll('td');
    for (let td of tds) {
      if (td.innerText.includes('ASIN:')) {
        const lines = td.innerText.split('\n').map(l => l.trim()).filter(Boolean);
        // Find line before ASIN
        const asinIdx = lines.findIndex(l => l.includes('ASIN:'));
        if (asinIdx > 0) {
          title = lines[asinIdx - 1];
        } else if (lines.length > 0) {
          title = lines[0];
        }
        break;
      }
    }

    return {
      orderId,
      orderDate,
      orderTime,
      channel,
      isBusiness,
      asin,
      sku,
      title,
      qty,
      subtotal
    };
  });

  return {
    totalParsed: parsed.length,
    orders: parsed
  };
}","pageId":3,"toolSummary":"Parse all 38 pending order rows individually"}

