{"function":"() => {
  const table = document.getElementById('orders-table');
  const trs = Array.from(table.querySelectorAll('tbody tr')).filter(tr => tr.querySelector('a[href*="/orders-v3/order/"]'));

  const parsed = trs.map(tr => {
    const text = tr.innerText;
    const link = tr.querySelector('a[href*="/orders-v3/order/"]');
    const orderId = link ? link.innerText.trim() : 'Unknown';

    const dateMatch = text.match(/(\d{4}\/\d{2}\/\d{2})\s*(\d{2}:\d{2}\s*[A-Z]{3})?/);
    const orderDate = dateMatch ? dateMatch[1] : 'Unknown';
    const orderTime = dateMatch ? (dateMatch[2] || '') : '';

    const channelMatch = text.match(/销售渠道:\s*([^\n\t]+)/);
    const channel = channelMatch ? channelMatch[1].trim() : 'Unknown';
    const isBusiness = text.includes('企业买家');

    const asinMatch = text.match(/ASIN:\s*([A-Z0-9]{10})/);
    const asin = asinMatch ? asinMatch[1] : 'Unknown';

    const skuMatch = text.match(/SKU:\s*([^\n\t]+)/);
    const sku = skuMatch ? skuMatch[1].trim() : 'Unknown';

    const qtyMatch = text.match(/数量:\s*(\d+)/);
    const qty = qtyMatch ? parseInt(qtyMatch[1], 10) : 1;

    const subtotalMatch = text.match(/商品小计:\s*([^\n\t]+)/);
    const subtotal = subtotalMatch ? subtotalMatch[1].trim() : 'Unknown';

    let title = 'Unknown';
    const tds = tr.querySelectorAll('td');
    for (let td of tds) {
      if (td.innerText.includes('ASIN:')) {
        const lines = td.innerText.split('\n').map(l => l.trim()).filter(Boolean);
        const asinIdx = lines.findIndex(l => l.includes('ASIN:'));
        if (asinIdx > 0) {
          title = lines[asinIdx - 1];
        } else if (lines.length > 0) {
          title = lines[0];
        }
        break;
      }
    }

    return { orderId, orderDate, orderTime, channel, isBusiness, asin, sku, title, qty, subtotal };
  });

  // Date distribution
  const dateCounts = {};
  parsed.forEach(o => {
    dateCounts[o.orderDate] = (dateCounts[o.orderDate] || 0) + 1;
  });

  const oct29Orders = parsed.filter(o => o.orderDate === '2026/10/29');
  const oct28Orders = parsed.filter(o => o.orderDate === '2026/10/28');
  const earlierOrders = parsed.filter(o => o.orderDate !== '2026/10/29' && o.orderDate !== '2026/10/28');

  // Top products for Oct 29 (by order count and total units)
  const oct29Products = {};
  oct29Orders.forEach(o => {
    const key = o.asin;
    if (!oct29Products[key]) {
      oct29Products[key] = {
        asin: o.asin,
        sku: o.sku,
        title: o.title,
        orderCount: 0,
        totalUnits: 0,
        orders: []
      };
    }
    oct29Products[key].orderCount += 1;
    oct29Products[key].totalUnits += o.qty;
    oct29Products[key].orders.push(o.orderId);
  });

  const topOct29ProductsByOrders = Object.values(oct29Products).sort((a, b) => b.orderCount - a.orderCount || b.totalUnits - a.totalUnits);

  return {
    totalPending: parsed.length,
    dateDistribution: dateCounts,
    oct29Count: oct29Orders.length,
    oct28Count: oct28Orders.length,
    earlierCount: earlierOrders.length,
    earlierBreakdown: earlierOrders.map(o => ({ orderId: o.orderId, date: o.orderDate, asin: o.asin, sku: o.sku, qty: o.qty })),
    topOct29Products: topOct29ProductsByOrders
  };
}","pageId":3,"toolSummary":"Compute exact pending order statistics"}

