{"function":"async () => {
  const asins = ['B07FKL263W', 'B07FKHHTY4', 'B07FKJM2LX', 'B07RP9MB7Y', 'B01M3N310M', 'B07FKJLZNG', 'B07JVSYNYV', 'B07K8L4K8K'];
  const results = {};
  for (const asin of asins) {
    try {
      const res = await fetch(`https://www.amazon.com/dp/${asin}`);
      const text = await res.text();
      const parser = new DOMParser();
      const doc = parser.parseFromString(text, 'text/html');
      const title = doc.querySelector('#productTitle')?.innerText?.trim() || '';
      const rating = doc.querySelector('#acrPopover')?.getAttribute('title')?.trim() || doc.querySelector('.a-icon-alt')?.innerText?.trim() || '';
      const reviewCount = doc.querySelector('#acrCustomerReviewText')?.innerText?.trim() || '';
      results[asin] = { title, rating, reviewCount };
    } catch (e) {
      results[asin] = { error: e.message };
    }
  }
  return results;
}","pageId":8,"toolSummary":"Fetch PDP details for ASINs","waitForStableDom":false}

