() => {
  // Find any row menu in Manage Inventory
  const rows = document.querySelectorAll('tr, div[data-testid]');
  const links = Array.from(document.querySelectorAll('a')).map(a => ({ text: a.innerText, href: a.href }));
  return links.filter(l => l.text.includes('变体') || l.text.includes('合并') || l.text.includes('重复'));
}
